export function Marquee({ items }: { items: string[] }) {
  const loop = [...items, ...items];

  return (
    <div
      className="group relative w-full overflow-hidden"
      style={{
        maskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
        WebkitMaskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
      }}
    >
      <style>{`@keyframes marquee-scroll { to { transform: translateX(-50%); } }`}</style>
      <div className="flex w-max animate-[marquee-scroll_16s_linear_infinite] gap-8 group-hover:[animation-play-state:paused] motion-reduce:animate-none">
        {loop.map((item, i) => (
          <span key={i} className="whitespace-nowrap text-sm font-medium text-slate-500 dark:text-slate-400">
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}
